#include "eternity/game/character_recovery.hpp"
#include "eternity/game/creation.hpp"
#include <iostream>

using namespace eternity;using namespace eternity::game;
namespace {
void require(bool value,const char* message) {if(!value) throw std::runtime_error(message);}
void put(net::Packet& p,std::uint64_t value,unsigned int count) {for(unsigned int i=0;i<count;++i) p.push_back(static_cast<std::uint8_t>(value>>(8*i)));}
net::Packet packet(std::uint16_t op) {net::Packet p;put(p,op,2);put(p,9801,4);return p;}
net::Packet receipt(std::uint16_t op,std::uint8_t source,std::uint8_t slot,std::uint64_t uid) {auto p=packet(op);p.insert(p.end(),{source,0,slot});put(p,uid,8);put(p,5001,4);p.insert(p.end(),{5,1,3});put(p,100,2);p.insert(p.end(),{1,2,3,4,5,6});const std::string craft="01020304050607080903";p.insert(p.end(),craft.begin(),craft.end());p.push_back(0);put(p,pack_world_time(std::chrono::sys_days{std::chrono::year{2024}/2/29}),4);p.push_back('U');return p;}
std::string command(const RecoveryOperation& op,const std::string& prefix) {const auto line=recovery_sql(op);const auto start=line.find(op.procedure)+op.procedure.size()+1;auto args=line.substr(start);if(op.odbc) args.resize(args.size()-2);return "EXEC "+prefix+op.procedure+' '+args+';';}
}
int main(int argc,char** argv) {
    try {
        require(argc==2 && std::string_view(argv[1]).starts_with("Eternity_Test_Creation_"),"Recovery SQL test requires disposable catalog");const std::string catalog=argv[1],prefix="["+catalog+"].dbo.";storage::SqlServer db(storage::SqlServerConfig::from_environment());const auto definitions=Definitions::load(db);const auto rules=CreationRules::load(definitions);const auto time=std::chrono::sys_days{std::chrono::year{2024}/1/1};Characters characters(db,1,time,catalog);require(characters.save_country(9801,0,true),"Cannot initialize recovery account");auto draft=rules.prepare({0,0,2,0,0,0,0,0,"RecoverHero"},0);draft.items.clear();const auto created=characters.create(9801,"recover_user",draft,time);require(created.result==0,"Cannot create recovery fixture character");const auto cid=std::to_string(created.character_id);
        db.query("INSERT "+prefix+"Users_Product(UserUID,Slot,ItemID,ItemCount,ProductCode,OrderNumber,VerifyCode,BuyDate) VALUES(9801,0,5001,3,'recovery_product',111,222,'20240101'); INSERT "+prefix+"UserStoredPointItems(UserUID,Slot,ItemID,ItemCount) VALUES(9801,239,5001,3); EXEC "+prefix+"usp_Save_Char_Quest_Add_E "+cid+",5,10,0,0,0; EXEC "+prefix+"usp_Save_Char_Item_Add_E 880001,123456789,1,0,5001,5,1,100,0,0,0,0,0,0,'',1,'20240101','U';");
        PlayerCore initial;initial.user_id=9801;initial.character=draft.character;initial.character.id=created.character_id;initial.character.level=30;initial.stored_money=5000000000ULL;InventoryReplicaPool pool;CharacterReplica cache(initial,pool);cache.growth().load(0);const auto apply=[&](const net::Packet& p){require(cache.apply(p)==InventoryReplicaResult::applied,"Cannot stage recovery command");};
        auto body=packet(0x615);body.insert(body.end(),{1,2,3,1});apply(body);PlayerItem item;item.uid=123456789;item.id=5001;item.bag=1;item.type=5;item.type_id=1;item.quality=100;item.count=7;item.made_at=pack_world_time(time);item.make_type="U";require(cache.inventory().load(item,false,1),"Cannot seed recovery insert");
        const std::array<PlayerPointItem,1> product{{{0,5001,3}}},stored{{{239,5001,3}}};cache.points().load_products(product);cache.points().load_stored(stored);apply(receipt(0x710,0,0,0x7777000000000b00ULL));apply(receipt(0xe05,239,1,0x7777000000000b01ULL));
        require(cache.quests().load({5,10,{0,0,0}}),"Cannot seed recovery quest");auto cancel=packet(0xa02);put(cancel,5,2);cancel.push_back(2);apply(cancel);auto quest=packet(0xa01);put(quest,6,2);put(quest,20,2);apply(quest);const std::array<PersistedEffect,1> expired{{{7,1,0}}};require(cache.skills().load({},expired),"Cannot seed zero-time effect");
        const std::array<QuickSlot,1> quick{{{1,2,1,3}}};require(cache.interface().load_quick_slots(quick),"Cannot seed recovery quick slot");auto point=packet(0xd02);point.push_back(0);put(point,20,2);put(point,0x3f800000,4);put(point,0x40000000,4);put(point,0x40400000,4);apply(point);auto market=packet(0x61a);market.push_back(1);put(market,5,4);apply(market);
        const auto plan=capture_character_recovery(cache,1);require(!cache.body_changed() && cache.inventory().inventory().back().save_type==0 && cache.quests().deleted().empty() && cache.points().products()[0].save_type==0 && cache.points().stored()[0].second.save_type==3 && cache.interface().points()[0].save_type==1 && cache.market().save_type()==1,"Recovery did not preserve distinct original acknowledgment rules");
        bool old_core=false,old_product=false,expired_emitted=false;
        for(const auto& op:plan) {
            if(op.procedure=="usp_Save_Char_Info_E" || op.procedure=="usp_Save_Char_Product_Item_E") {
                bool failed=false;try{db.query(command(op,prefix));}catch(const std::runtime_error&){failed=true;}require(failed,"Legacy recovery envelope silently acquired live SQL parameters");if(op.procedure=="usp_Save_Char_Info_E") old_core=true;else old_product=true;
            }
            if(op.procedure=="usp_Save_Char_ApplySkill_Add_E2" && std::get<std::int64_t>(op.parameters[3])==0) expired_emitted=true;
        }
        require(old_core && old_product && expired_emitted,"Recovery compatibility cases were not captured");
        const auto replay_compatible=[&](){for(const auto& op:plan) if(op.procedure!="usp_Save_Char_Info_E" && op.procedure!="usp_Save_Char_Product_Item_E") db.query(command(op,prefix));};
        db.begin();replay_compatible();db.rollback();auto rows=db.query("SELECT CharID FROM "+prefix+"CharItems WHERE ItemUID=123456789; SELECT COUNT(*) FROM "+prefix+"UserStoredPointItems WHERE UserUID=9801; SELECT QuestID FROM "+prefix+"CharQuests WHERE CharID="+cid+"; SELECT COUNT(*) FROM "+prefix+"CharApplySkills WHERE CharID="+cid+"; SELECT COUNT(*) FROM "+prefix+"UserStoredMoney WHERE UserUID=9801;");require(rows[0].rows[0][0]==storage::Cell{"880001"} && rows[1].rows[0][0]==storage::Cell{"1"} && rows[2].rows[0][0]==storage::Cell{"5"} && rows[3].rows[0][0]==storage::Cell{"0"} && rows[4].rows[0][0]==storage::Cell{"0"},"Recovery statement rollback reached committed fixture data");require(cache.quests().deleted().empty() && cache.inventory().inventory().back().save_type==0,"SQL rollback restored the original file-cleared cache markers");
        db.begin();replay_compatible();db.commit();rows=db.query("SELECT CharID,[Count] FROM "+prefix+"CharItems WHERE ItemUID=123456789; SELECT COUNT(*) FROM "+prefix+"UserStoredPointItems WHERE UserUID=9801; SELECT QuestID FROM "+prefix+"CharQuests WHERE CharID="+cid+"; SELECT LeftResetTime FROM "+prefix+"CharApplySkills WHERE CharID="+cid+"; SELECT Money FROM "+prefix+"UserStoredMoney WHERE UserUID=9801; SELECT COUNT(*) FROM "+prefix+"Users_Product WHERE UserUID=9801; SELECT COUNT(*) FROM "+prefix+"CharQuickSlots WHERE CharID="+cid+"; SELECT MapID FROM "+prefix+"CharSavePoint WHERE CharID="+cid+";");require(rows[0].rows[0]==storage::Row{storage::Cell{cid},storage::Cell{"7"}} && rows[1].rows[0][0]==storage::Cell{"0"} && rows[2].rows[0][0]==storage::Cell{"6"} && rows[3].rows[0][0]==storage::Cell{"0"} && rows[4].rows[0][0]==storage::Cell{"705032704"} && rows[5].rows[0][0]==storage::Cell{"1"} && rows[6].rows[0][0]==storage::Cell{"1"} && rows[7].rows[0][0]==storage::Cell{"20"},"Compatible recovery procedures changed original UID delete/insert, receipt, journal, effect, money or UI contracts");
        std::cout<<"Original file recovery SQL passed: legacy envelope failures, separate stored money, global UID delete-before-add, expired effects, consumed journals, rollback and compatible statement replay\n";
    }catch(const std::exception& error) {std::cerr<<error.what()<<'\n';return 1;}
}
